/* mg-job-cards */ SELECT year_key, MAX(financial_year_short) AS financial_year, SUM(job_cards_issued_total) AS job_cards_issued
FROM curated.v_employment WHERE UPPER(lgd_district) = UPPER('EAST JAINTIA HILLS') AND year_key = 2024
GROUP BY year_key ORDER BY year_key

SELECT COUNT(DISTINCT beneficiary_key) AS beneficiaries
FROM curated.v_focus_plus
WHERE lgd_district = 'RI BHOI';
